/**
 * scripts/inject-ios-icons.mjs
 *
 * Overwrites the iOS asset catalog at
 * `ios/App/App/Assets.xcassets/AppIcon.appiconset/` and
 * `ios/App/App/Assets.xcassets/Splash.imageset/` with the Noesis emblem
 * generated by `regenerate-icons.mjs`.
 *
 * Background: `npx cap add ios` scaffolds the iOS project from the
 * Capacitor template, which ships a blue-X placeholder app icon.
 * Without this step, every CI build embeds that placeholder, which is
 * exactly what Apple App Review Guideline 2.3.8 rejects ("the app
 * icons appear to be placeholder icons"). Capacitor 6 uses the
 * iOS-14+ "single 1024" format: one PNG named `AppIcon-512@2x.png`
 * with `idiom=universal`, `platform=ios`, `size=1024x1024`. We just
 * need to overwrite that file (and its splash counterparts) and the
 * asset catalog is correct.
 *
 * Run AFTER `npx cap sync ios`:
 *   node scripts/inject-ios-icons.mjs
 */

import { copyFileSync, existsSync, mkdirSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");
const ICON_SRC = join(ROOT, "noesis-icon-1024.png");
const SPLASH_SRC = join(ROOT, "noesis-splash-2732.png");

if (!existsSync(ICON_SRC)) {
  console.error(`Missing ${ICON_SRC}. Run scripts/regenerate-icons.mjs first.`);
  process.exit(1);
}
if (!existsSync(SPLASH_SRC)) {
  console.error(`Missing ${SPLASH_SRC}. Run scripts/regenerate-icons.mjs first.`);
  process.exit(1);
}

const IOS_ROOT = join(ROOT, "ios", "App", "App", "Assets.xcassets");
if (!existsSync(IOS_ROOT)) {
  console.error(`iOS asset catalog not found at ${IOS_ROOT}.`);
  console.error(`Run 'npx cap add ios' or 'npx cap sync ios' before injecting icons.`);
  process.exit(1);
}

// 1. AppIcon.appiconset - Capacitor 6's single-1024 layout.
const APPICON_DIR = join(IOS_ROOT, "AppIcon.appiconset");
mkdirSync(APPICON_DIR, { recursive: true });
const appIconDest = join(APPICON_DIR, "AppIcon-512@2x.png");
copyFileSync(ICON_SRC, appIconDest);
const appIconJson = {
  images: [
    {
      filename: "AppIcon-512@2x.png",
      idiom: "universal",
      platform: "ios",
      size: "1024x1024",
    },
  ],
  info: { author: "xcode", version: 1 },
};
writeFileSync(
  join(APPICON_DIR, "Contents.json"),
  JSON.stringify(appIconJson, null, 2) + "\n"
);
console.log(`  app icon -> ${appIconDest}`);

// 2. Splash.imageset - three filenames, one image (Capacitor template
// references them at 1x/2x/3x scales but they share the same composition).
const SPLASH_DIR = join(IOS_ROOT, "Splash.imageset");
if (existsSync(SPLASH_DIR)) {
  for (const name of ["splash-2732x2732.png", "splash-2732x2732-1.png", "splash-2732x2732-2.png"]) {
    copyFileSync(SPLASH_SRC, join(SPLASH_DIR, name));
    console.log(`  splash -> ${join(SPLASH_DIR, name)}`);
  }
} else {
  console.warn(`(Splash.imageset not found at ${SPLASH_DIR}; skipping splash injection.)`);
}

console.log("\niOS asset catalog updated with Noesis emblem.");
